#' Library
#'
#' Manages the scenario library of the Study Simulator: reads a custom library 
#' (YAML, Excel, JSON or a zip of them), checks it, shows its scenarios, and 
#' exports the library or one scenario as Excel, JSON or YAML, or an Excel 
#' template to start a new one.
#' 
#'
#' @examples
#' \donttest{
#' # studysim:::check_library(studysim:::builtin_library())
#'}
#' @param data .
#' @param libName .
#' @param libContent .
#' @param source .
#' @param scenario .
#' @param showScenarios .
#' @param showProblems .
#' @param showDetails .
#' @param exportFormat .
#' @param exportScope .
#' @param exportLib .
#' @param exportTemplate .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$scenarios} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$problems} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$variables} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structure} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$about} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$exportState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$templateState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$scenarios$asDF}
#'
#' \code{as.data.frame(results$scenarios)}
#'
#' @export
simLibrary <- function(
    data,
    libName = "",
    libContent = "",
    source = "merged",
    scenario = "breast_cancer_risk",
    showScenarios = TRUE,
    showProblems = TRUE,
    showDetails = TRUE,
    exportFormat = "xlsx",
    exportScope = "all",
    exportLib = FALSE,
    exportTemplate = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simLibrary requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- simLibraryOptions$new(
        libName = libName,
        libContent = libContent,
        source = source,
        scenario = scenario,
        showScenarios = showScenarios,
        showProblems = showProblems,
        showDetails = showDetails,
        exportFormat = exportFormat,
        exportScope = exportScope,
        exportLib = exportLib,
        exportTemplate = exportTemplate)

    analysis <- simLibraryClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

